css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--clay:#8C5B46;--gilt:#C6A15B;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.narrow{max-width:1000px}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.hero{background:var(--ink);color:var(--bone);text-align:center;padding:96px 0 0}
.hero:before{content:"";position:absolute;top:0;left:0;right:0;bottom:-226px;background:radial-gradient(55% 45% at 50% 30%,rgba(140,91,70,.16),rgba(1,10,18,0) 70%);pointer-events:none;z-index:1}
.hero .in{container-type:inline-size}
.sigil{display:block;width:46cqi;height:auto;margin:0 auto 48px;overflow:visible}
.sigil circle{fill:none;stroke:var(--gilt);stroke-width:.55;stroke-dasharray:180;stroke-dashoffset:180;animation:pwdraw 3.2s cubic-bezier(.4,0,.2,1) forwards}
.sigil circle+circle{animation-delay:.5s}
@keyframes pwdraw{to{stroke-dashoffset:0}}
.hero h1{margin:22px 0 0;font-family:var(--label);font-weight:300;text-transform:uppercase;font-size:calc(100cqi / 9.66209);line-height:1.05;letter-spacing:0;color:var(--bone);white-space:nowrap;text-align:left}
.hero h1 .t{display:inline-block;letter-spacing:.32em;margin-left:-.12em}
.hero .sub{margin:44px 0 0;font-family:var(--label);font-weight:300;text-transform:uppercase;font-size:23px;line-height:1.3;color:var(--stone);white-space:nowrap;text-align:left}
.hero .sub .s{display:inline-block;letter-spacing:calc((100cqi - 502.3897px) / 34)}
.hero .left{text-align:left}
.hero .left .rule{margin:96px 0 32px}
.hero .lead{margin:0;font-family:var(--head);font-weight:500;font-size:32px;line-height:1.3;max-width:24em;text-wrap:balance}
.hero .body{margin:28px 0 0;max-width:36em;color:var(--stone)}
.hero .fl{margin:48px 0 0;font-family:var(--label);font-size:12px;letter-spacing:.3em;color:var(--sand)}
.hero .anim{opacity:0;transform:translateY(14px);animation:pwrise 1.6s ease forwards}
.hero .a1{animation-delay:1.7s}
.hero .a2{animation-delay:2.2s}
.hero .a3{animation-delay:2.7s}
.hero .a4{animation-delay:3.1s}
@keyframes pwrise{to{opacity:1;transform:none}}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.hero{padding-top:64px}.hero:before{bottom:-280px}.sigil{margin-bottom:34px}.hero h1{font-size:calc(100cqi / 8.76209)}.hero h1 .t{letter-spacing:.22em}.hero .sub{font-size:12px;margin-top:26px}.hero .sub .s{letter-spacing:calc((100cqi - 262.1164px) / 34)}.hero .left .rule{margin:64px 0 32px}.hero .lead{font-size:25px}}
@media (prefers-reduced-motion:reduce){.sigil circle{animation:none;stroke-dashoffset:0}.hero .anim{animation:none;opacity:1;transform:none}}
